using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "IndigoSoulCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/IndigoSoulCustomDescription", order = 0)]
public class IndigoSoulCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private RefreshAction refreshAction;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return Smart.Format(GetRawLocalizedDescription(battleAction), refreshAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)).RemoveLast(), GetAmountWithoutEquation(amountModified));
	}
}
